import numpy as np, itertools
from pfapack.pfaffian import pfaffian as pf
W,H=3,5; N=W*H
def sid(x,y): return (y%H)*W+(x%W)
edges=[(x,y,d) for y in range(H) for x in range(W) for d in 'EN']
def even_gen(t):
    # brute force over spins: Z/(2^N prod cosh) = sum_even prod t ; compute via spins
    tot=0
    for c in range(2**N):
        s=1-2*((c>>np.arange(N))&1)
        w=1
        for k,(x,y,d) in enumerate(edges):
            v=sid(x+1,y) if d=='E' else sid(x,y+1)
            w*=(1+t[k]*s[sid(x,y)]*s[v])
        tot+=w
    return tot/2**N
rng=np.random.default_rng(0)
ts=[rng.uniform(-.5,.8,len(edges)) for _ in range(3)]
Zs=[even_gen(t) for t in ts]
print(Zs)
pairs=list(itertools.combinations(range(4),2))
def build(t,loc,oE,oN,a,b):
    A=np.zeros((4*N,4*N))
    for i in range(N):
        for (p,q),s in zip(pairs,loc): A[4*i+p,4*i+q]=s; A[4*i+q,4*i+p]=-s
    for k,(x,y,d) in enumerate(edges):
        if d=='E': u,v,sg=4*sid(x,y)+0,4*sid(x+1,y)+1,oE*(a if x==W-1 else 1)
        else: u,v,sg=4*sid(x,y)+2,4*sid(x,y+1)+3,oN*(b if y==H-1 else 1)
        A[u,v]=t[k]*sg; A[v,u]=-t[k]*sg
    return A
for loc in itertools.product([1,-1],repeat=6):
  for oE in [1,-1]:
    for oN in [1,-1]:
      M=[[pf(build(t,loc,oE,oN,a,b)) for a in [1,-1] for b in [1,-1]] for t in ts]
      c,res,_,_=np.linalg.lstsq(np.array(M),np.array(Zs),rcond=None)
      if np.abs(np.array(M)@c-Zs).max()<1e-9: print(loc,oE,oN,c)
